"""
Server-side validation for the registration wizard.
No Reflex imports — plain Python only.
"""

import re


def _is_valid_email(email: str) -> bool:
    """Return True if *email* has a non-empty local part, a single '@', and a
    domain with at least one dot."""
    parts = email.split("@")
    if len(parts) != 2:
        return False
    local, domain = parts
    if not local:
        return False
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return False
    return True


def validate_step(step: int, data: dict) -> dict:
    """Validate the given wizard step.

    Parameters
    ----------
    step:
        1, 2, or 3 — the step to validate.
    data:
        Dict that may contain any of: email, password, confirm_password,
        full_name, accept_terms.

    Returns
    -------
    dict
        Maps each invalid field name to an error message string.
        Empty dict when the step is fully valid.
    """
    errors: dict = {}

    if step == 1:
        email = data.get("email", "")
        if not isinstance(email, str) or not email.strip():
            errors["email"] = "Email is required"
        elif not _is_valid_email(email.strip()):
            errors["email"] = "Invalid email address"

    elif step == 2:
        password = data.get("password", "")
        confirm = data.get("confirm_password", "")

        if not isinstance(password, str) or len(password) < 8:
            errors["password"] = "Password must be at least 8 characters"
        elif not any(c.isupper() for c in password):
            errors["password"] = "Password must contain an uppercase letter"
        elif not any(c.islower() for c in password):
            errors["password"] = "Password must contain a lowercase letter"
        elif not any(c.isdigit() for c in password):
            errors["password"] = "Password must contain a digit"

        if confirm != password:
            errors["confirm_password"] = "Passwords do not match"

    elif step == 3:
        full_name = data.get("full_name", "")
        accept_terms = data.get("accept_terms", False)

        if not isinstance(full_name, str) or not full_name.strip():
            errors["full_name"] = "Full name is required"
        if not accept_terms:
            errors["accept_terms"] = "You must accept the terms"

    return errors

